/*
 * A001275  Smallest prime p such that the product of q/(q-1) over the primes
 *          from prime(n) to p is greater than 2.
 * https://oeis.org/A001275
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   search, not a closed form. Odd primes are generated by a
 *            segmented sieve. Starting at prime(n), add log(q/(q-1)) for each
 *            prime q (Kahan- compensated long double sum) and return the
 *            first p at which the sum exceeds log 2. For n = 1 the product
 *            2/1 equals exactly 2, which is not greater than 2, so...
 * Range:     u8 n <= 6, u16 n <= 52, u32 n <= 650, u64 n <= 650,
 *            u128 n <= 650, big any n
 * Validated: standard, pass, 56 terms through n = 617 (2026-11-01)
 * Helpers:   isqrt_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "../utils/isqrt_u64.h"

/* returns 0 if the answer is not found below limit L */
static uint64_t a1275_run(idx_t n, uint64_t L) {
    const long double LN2 = 0.693147180559945309417232121458176568L;
    uint64_t s = isqrt_u64(L) + 1, i, j;
    unsigned char *small = (unsigned char *)calloc((size_t)(s + 1), 1);
    uint32_t *bp = (uint32_t *)malloc(sizeof(uint32_t) * (size_t)(s / 2 + 2));
    size_t nb = 0;
    for (i = 3; i <= s; i += 2) {
        if (!small[i]) {
            bp[nb++] = (uint32_t)i;
            for (j = i * i; j <= s; j += 2 * i) small[j] = 1;
        }
    }
    free(small);

    const uint64_t SEG = 1u << 18; /* number of odd values per segment */
    unsigned char *mark = (unsigned char *)malloc((size_t)SEG);
    uint64_t count = 1; /* prime 2 already counted */
    int started = 0;
    long double sum = 0.0L, comp = 0.0L;
    uint64_t result = 0;
    uint64_t lo;
    for (lo = 3; lo <= L && !result; lo += 2 * SEG) {
        uint64_t hi = lo + 2 * SEG; /* exclusive */
        memset(mark, 0, (size_t)SEG);
        size_t k;
        for (k = 0; k < nb; k++) {
            uint64_t q = bp[k];
            if (q * q >= hi) break;
            uint64_t st = q * q;
            if (st < lo) {
                st = ((lo + q - 1) / q) * q;
                if ((st & 1) == 0) st += q;
            }
            for (j = st; j < hi; j += 2 * q) mark[(j - lo) >> 1] = 1;
        }
        for (i = 0; i < SEG; i++) {
            if (mark[i]) continue;
            uint64_t m = lo + 2 * i;
            if (m > L) break;
            if (!started) {
                count++;
                if (count == n) started = 1;
                else continue;
            }
            long double t = log1pl(1.0L / (long double)(m - 1));
            long double y = t - comp;
            long double z = sum + y;
            comp = (z - sum) - y;
            sum = z;
            if (sum > LN2) { result = m; break; }
        }
    }
    free(mark);
    free(bp);
    return result;
}

seq_t a(idx_t n) {
    if (n <= 1) return (seq_t)3;
    /* upper estimate for prime(n), then a(n) ~ prime(n)^2 */
    uint64_t pn;
    if (n < 6) pn = 13;
    else {
        long double ln = logl((long double)n);
        pn = (uint64_t)((long double)n * (ln + logl(ln))) + 3;
    }
    uint64_t L = 3 * pn * pn + 1000;
    for (;;) {
        uint64_t r = a1275_run(n, L);
        if (r) return (seq_t)r;
        L *= 4;
    }
}
